#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/collections/choice_group_values/choice_group_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ChoiceGroup's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/choice_group.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// How the choices are drawn: a row of buttons (the default) or a segmented control with a selection indicator behind the selected segment. Selection, keyboard and semantics are the same in both.
template <typename Declaring>
struct ChoiceGroupPresentationCapability {
    PropertyCell<ChoiceGroupPresentation, ChoiceGroupPresentationCapability<Declaring>> presentation{ChoiceGroupPresentation::buttons};

    static void assign(ChoiceGroupPresentationCapability& capability, ChoiceGroupPresentation incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.presentation), incoming);
        if (!capability.presentation.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.presentation));
    }
};

// The selected item's index, or -1 for none (G14: an ordinary cell). Outside the items throws std::out_of_range; a bound Value may refuse it. A change checks the selected item's button and raises changed.
template <typename Declaring>
struct ChoiceGroupSelectedIndexCapability {
    PropertyCell<int, ChoiceGroupSelectedIndexCapability<Declaring>> selected_index{-1};

    static void assign(ChoiceGroupSelectedIndexCapability& capability, int incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.selected_index), incoming);
        if (!capability.selected_index.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.selected_index));
    }
};

// ChoiceGroupPresentation as a property value; defined beside ChoiceGroup's table.
template <>
struct PropertyValueTraits<ChoiceGroupPresentation> {
    static PropertyType type();
    static BindingValue to_binding(ChoiceGroupPresentation value);
    static ChoiceGroupPresentation from_binding(const BindingValue& value);
};

// Every ChoiceGroup capability, in the order the declaring class takes them.
template <typename Declaring>
struct ChoiceGroupCapabilities : public ChoiceGroupPresentationCapability<Declaring>,
                                 public ChoiceGroupSelectedIndexCapability<Declaring> {};

} // namespace gui_forms
